<script setup lang="ts">
import { VisAxis, VisDonut, VisSingleContainer, VisStackedBar, VisXYContainer } from '@unovis/vue'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '~/components/ui/card'
import { Button } from '~/components/ui/button'
import { Skeleton } from '~/components/ui/skeleton'
import { Progress } from '~/components/ui/progress'
import { NativeSelect, NativeSelectOption } from '~/components/ui/native-select'
import { Input } from '~/components/ui/input'
import { formatTanggalWib, tanggalHariIniWib } from '~~/shared/utils/waktu'
definePageMeta({ layout: 'dashboard', title: 'Ringkasan UPT' })
const route = useRoute()
const kantorId = computed(() => String(route.params.kantorId))
const hariIni = tanggalHariIniWib()
const modePeriode = ref<'bulan_ini' | 'enam_bulan' | 'kustom'>('bulan_ini')
const mulaiKustom = ref(`${hariIni.slice(0, 7)}-01`)
const selesaiKustom = ref(hariIni)
const periode = computed(() => modePeriode.value === 'kustom' ? { mulai: mulaiKustom.value, selesai: selesaiKustom.value } : modePeriode.value === 'bulan_ini' ? { mulai: `${hariIni.slice(0, 7)}-01`, selesai: hariIni } : { mulai: new Date(Date.UTC(Number(hariIni.slice(0, 4)), Number(hariIni.slice(5, 7)) - 7, 1)).toISOString().slice(0, 10), selesai: hariIni })
const api = useApi()
type Tren = { laporan_per_bulan?: { bulan: string; wna: number; wni: number }[]; proporsi?: { wna: number; wni: number }; kegiatan_per_jenis?: { jenis: string; jumlah: number }[]; kandidat_dbi?: { desa_id: string; desa: string; kecamatan: string; jumlah: number }[] }
type DataUpt = { kantor: { nama: string; nama_singkat: string }; ringkasan: { perlu_ditanggapi: number; sedang_ditangani: number; terlambat: number; selesai_ditolak_bulan_ini: number; kegiatan_bulan_ini: number; batas_hari: number } | null; tindakan: { laporan_id: string; kode_pelacakan: string; desa: string; kecamatan: string; jenis_terlapor: string; masuk_pada: string; sisa_hari_kerja: number }[]; desa: { desa_id: string; desa: string; kecamatan: string; kabupaten: string; petugas: string; kegiatan_terakhir: string | null; hari_sejak_kegiatan: number | null; kegiatan_bulan_ini: number }[]; tren: unknown }
const { data, pending, error, refresh } = await useAsyncData<DataUpt>(`kanwil-lihat-upt-${route.params.kantorId}`, () => api<DataUpt>(`/api/kanwil/upt/${route.params.kantorId}`, { query: periode.value }), { watch: [periode] })
const tren = computed(() => data.value?.tren as Tren | null)
const nilaiMaksJenis = computed(() => Math.max(1, ...(tren.value?.kegiatan_per_jenis ?? []).map(item => item.jumlah)))
const proporsiWna = computed(() => tren.value?.proporsi?.wna ?? 0)
const proporsiWni = computed(() => tren.value?.proporsi?.wni ?? 0)
const dataDonat = computed(() => [{ jenis: 'WNA', jumlah: proporsiWna.value, warna: 'var(--chart-1)' }, { jenis: 'WNI', jumlah: proporsiWni.value, warna: 'var(--chart-3)' }])
const nilai = (item: { jumlah: number }) => item.jumlah
const warna = (item: { warna: string }) => item.warna
const xLaporan = (item: { bulan: string }) => new Date(`${item.bulan.slice(0, 7)}-01T00:00:00+07:00`).getTime()
const yWna = (item: { wna: number }) => item.wna
const yWni = (item: { wni: number }) => item.wni
const labelBulan = (value: number) => new Intl.DateTimeFormat('id-ID', { month: 'short', timeZone: 'Asia/Jakarta' }).format(new Date(value))
</script>
<template><div class="mx-auto grid w-full max-w-screen-2xl min-w-0 gap-5 sm:gap-6"><header class="flex min-w-0 flex-col gap-4 border-l-2 border-accent py-1 pl-4 sm:flex-row sm:items-end sm:justify-between"><div class="min-w-0"><Button as-child variant="ghost" class="-ml-3"><NuxtLink to="/kanwil">← Kembali ke dashboard</NuxtLink></Button><p class="text-sm font-semibold text-muted-foreground">Pemantauan UPT · hanya-baca</p><h1 class="text-2xl font-bold tracking-tight text-primary sm:text-3xl">{{ data?.kantor.nama ?? 'Dashboard UPT' }}</h1><p class="mt-1 text-sm text-muted-foreground">{{ data?.kantor.nama_singkat }}</p></div><div class="grid w-full gap-3 sm:w-auto sm:flex sm:flex-wrap sm:items-end"><label class="grid gap-1.5 text-sm font-medium">Periode<NativeSelect v-model="modePeriode"><NativeSelectOption value="bulan_ini">Bulan ini</NativeSelectOption><NativeSelectOption value="enam_bulan">6 bulan terakhir</NativeSelectOption><NativeSelectOption value="kustom">Rentang bebas</NativeSelectOption></NativeSelect></label><template v-if="modePeriode === 'kustom'"><label class="grid gap-1.5 text-sm font-medium">Dari<Input v-model="mulaiKustom" type="date" :max="selesaiKustom" /></label><label class="grid gap-1.5 text-sm font-medium">Sampai<Input v-model="selesaiKustom" type="date" :min="mulaiKustom" :max="hariIni" /></label></template></div></header><div v-if="pending" class="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Skeleton v-for="i in 5" :key="i" class="h-28" /></div><Card v-else-if="error" role="alert"><CardHeader><CardTitle>Dashboard UPT belum dapat dimuat</CardTitle><CardDescription>Periksa koneksi atau akses kantor.</CardDescription></CardHeader><CardContent><Button variant="outline" @click="refresh()">Coba lagi</Button></CardContent></Card><template v-else-if="data?.ringkasan"><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Card v-for="item in [{ label: 'Perlu ditanggapi', value: data.ringkasan.perlu_ditanggapi }, { label: 'Sedang ditangani', value: data.ringkasan.sedang_ditangani }, { label: 'Terlambat', value: data.ringkasan.terlambat }, { label: 'Selesai atau ditolak bulan ini', value: data.ringkasan.selesai_ditolak_bulan_ini }, { label: 'Kegiatan PIMPASA bulan ini', value: data.ringkasan.kegiatan_bulan_ini }]" :key="item.label"><CardHeader><CardDescription>{{ item.label }}</CardDescription><CardTitle class="text-3xl tabular-nums">{{ item.value }}</CardTitle></CardHeader></Card></section><Card><CardHeader><CardTitle>Perlu tindakan</CardTitle><CardDescription>Laporan diterima yang menunggu tanggapan.</CardDescription></CardHeader><CardContent><ul v-if="data.tindakan.length" class="divide-y"><li v-for="item in data.tindakan" :key="item.laporan_id" class="flex flex-wrap justify-between gap-3 py-3"><div><p class="font-mono font-semibold">{{ item.kode_pelacakan }}</p><p class="text-sm text-muted-foreground">{{ item.desa }}, {{ item.kecamatan }} · {{ item.jenis_terlapor.toUpperCase() }} · {{ formatTanggalWib(item.masuk_pada) }}</p></div><span class="text-sm font-medium" :class="item.sisa_hari_kerja < 0 ? 'text-destructive' : 'text-muted-foreground'">{{ item.sisa_hari_kerja < 0 ? `Terlambat ${Math.abs(item.sisa_hari_kerja)} hari kerja` : `Sisa ${item.sisa_hari_kerja} hari kerja` }}</span></li></ul><p v-else class="text-sm text-muted-foreground">Tidak ada laporan yang perlu ditanggapi.</p></CardContent></Card><section class="grid gap-4 lg:grid-cols-2"><Card><CardHeader><CardTitle>Desa binaan</CardTitle></CardHeader><CardContent><ul class="grid gap-3"><li v-for="item in data.desa" :key="item.desa_id" class="rounded-lg border p-4"><p class="font-medium">{{ item.desa }}</p><p class="text-sm text-muted-foreground">{{ item.kecamatan }}, {{ item.kabupaten }} · PIMPASA: {{ item.petugas || 'Belum ada petugas' }}</p><p class="mt-2 text-sm">Kegiatan terakhir: {{ item.kegiatan_terakhir ? formatTanggalWib(item.kegiatan_terakhir) : 'Belum pernah' }} · {{ item.kegiatan_bulan_ini }} kegiatan bulan ini</p></li></ul><p v-if="!data.desa.length" class="text-sm text-muted-foreground">Belum ada desa binaan.</p></CardContent></Card><div class="grid content-start gap-4"><Card><CardHeader><CardTitle>Komposisi laporan</CardTitle><CardDescription>WNA {{ proporsiWna }}% · WNI {{ proporsiWni }}%</CardDescription></CardHeader><CardContent><ClientOnly><ChartContainer :config="{ wna: { label: 'WNA', color: 'var(--chart-1)' }, wni: { label: 'WNI', color: 'var(--chart-3)' } }" label="Komposisi laporan WNA dan WNI"><VisSingleContainer :height="200"><VisDonut :data="dataDonat" :value="nilai" :color="warna" :central-label="`${proporsiWna + proporsiWni}%`" :arc-width="24" /></VisSingleContainer></ChartContainer></ClientOnly></CardContent></Card><Card><CardHeader><CardTitle>Kegiatan per jenis</CardTitle></CardHeader><CardContent><ul class="grid gap-3"><li v-for="item in tren?.kegiatan_per_jenis ?? []" :key="item.jenis" class="text-sm"><div class="mb-1 flex justify-between"><span>{{ item.jenis }}</span><span>{{ item.jumlah }}</span></div><Progress :model-value="item.jumlah / nilaiMaksJenis * 100" /></li></ul></CardContent></Card></div></section><section class="grid gap-4 lg:grid-cols-2"><Card><CardHeader><CardTitle>Laporan per bulan</CardTitle></CardHeader><CardContent><ClientOnly><ChartContainer :config="{ wna: { label: 'WNA', color: 'var(--chart-1)' }, wni: { label: 'WNI', color: 'var(--chart-3)' } }" label="Tren laporan per bulan"><VisXYContainer :data="tren?.laporan_per_bulan ?? []" :height="240"><VisStackedBar :x="xLaporan" :y="[yWna, yWni]" :color="['var(--chart-1)', 'var(--chart-3)']" :rounded-corners="4" /><VisAxis type="x" :x="xLaporan" :tick-format="labelBulan" :tick-line="false" :domain-line="false" /><VisAxis type="y" :tick-line="false" :domain-line="false" /></VisXYContainer></ChartContainer></ClientOnly></CardContent></Card><Card><CardHeader><CardTitle>Kandidat desa non-DBI</CardTitle><CardDescription>Dapat diusulkan ke Kanwil di luar aplikasi.</CardDescription></CardHeader><CardContent><ol class="list-inside list-decimal"> <li v-for="item in tren?.kandidat_dbi ?? []" :key="item.desa_id" class="py-1">{{ item.desa }}, {{ item.kecamatan }} · {{ item.jumlah }} laporan</li></ol></CardContent></Card></section><div class="flex flex-wrap gap-3"><Button as-child><NuxtLink :to="`/kanwil/laporan?kantorId=${kantorId}`">Lihat laporan</NuxtLink></Button><Button as-child variant="outline"><NuxtLink :to="`/kanwil/kegiatan?kantorId=${kantorId}`">Lihat kegiatan</NuxtLink></Button><Button as-child variant="outline"><NuxtLink :to="`/kanwil/pantauan?kantorId=${kantorId}`">Pantauan terlambat</NuxtLink></Button></div></template></div></template>
